import{i as s}from"./chunks/important.CGe7Cw6H.js";import{Q as a,j as i,g as t,n as o,o as n,ay as r,m as c}from"./chunks/framework.COywXlYp.js";import"./chunks/alert.lvX7qW8X.js";/* empty css                                                                                  *//* empty css                                                                         */const f=JSON.parse('{"title":"Frequently Asked Questions","description":"","frontmatter":{"layout":"doc","title":"Frequently Asked Questions"},"headers":[],"relativePath":"en/guide/faq.md","filePath":"en/guide/faq.md"}'),l={name:"en/guide/faq.md"},b=Object.assign(l,{setup(d){return(p,e)=>(a(),i("div",null,[e[1]||(e[1]=t("h1",{id:"frequently-asked-questions",tabindex:"-1"},[o("Frequently Asked Questions "),t("a",{class:"header-anchor",href:"#frequently-asked-questions","aria-label":'Permalink to "Frequently Asked Questions"'},"​")],-1)),n(s,{title:"Important"},{default:r(()=>[...e[0]||(e[0]=[o(" All paths in this page are relative to the clickmouse installation directory. If Windows cannot open the files mentioned inside, please try opening with Notepad. ",-1)])]),_:1}),e[2]||(e[2]=c('<h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><p><strong>1. Language pack does not exist:</strong></p><p>Please check if there is a langs directory in clickmouse&#39;s <code>res</code> directory. If yes, check if there is a <code>langs.json</code> file inside. If not, please reinstall clickmouse. <a href="https://github.com/xystudiocode/pyClickMouse/releases/latest" target="_blank" rel="noreferrer">Download link</a></p><img class="lang_not_found" alt="Language pack not found"><p><strong>2. Cannot start:</strong></p><p>There might be some bugs. You can modify the content in <code>packages.json</code> to:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;xystudio.clickmouse&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;xystudio.clickmouse.repair&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>Then run the <code>repair.exe</code> file in the current directory, check the content you want to clear, click the <code>Repair</code> button, and start clickmouse again to see.</p><div class="tip custom-block"><p class="custom-block-title">Tip</p><p>It is recommended to select all repair items, but this will delete all user data and extensions, restoring to initial state.</p></div><p>If you can compile source code, you can also try using makefile, remove the <code>--windows-console-mode=disable</code> from compiling source code to get error stack trace.</p><p>If still not working, try uninstalling and reinstalling clickmouse. <a href="https://github.com/xystudiocode/pyClickMouse/releases/latest" target="_blank" rel="noreferrer">Download link</a></p><p>If the problem persists, you can <a href="https://github.com/xystudiocode/pyClickMouse/issues/new/choose" target="_blank" rel="noreferrer">report an issue</a></p><p><strong>3. Cannot connect to update, showing <code>timeout</code>:</strong></p><p>Our update content is stored on GitHub, and the network in China is slower.</p><p>You can install <a href="https://gitee.com/rmbgame/SteamTools/releases/download/3.0.0-rc.16/Steam%20%20_v3.0.0-rc.16_win_x64.exe" target="_blank" rel="noreferrer">watt toolkit</a> Then:</p><ol><li>Open watt toolkit, click <code>Network Acceleration</code> on the left</li><li>Check <code>github</code></li><li>Click <code>One-click Acceleration</code></li></ol><blockquote><p>This method can only ensure no timeout error, but cannot guarantee fast network speed.</p></blockquote><p>If still not working, I have no more methods</p><h2 id="software-function-usage-issues" tabindex="-1">Software Function Usage Issues <a class="header-anchor" href="#software-function-usage-issues" aria-label="Permalink to &quot;Software Function Usage Issues&quot;">​</a></h2><p><strong>1. Why is the click button grayed out?</strong></p><p>You may not have correctly entered click delay and click count. You can set click time and click count in the input boxes below, and select the unit for click count/delay in the dropdown box.</p><div class="warning custom-block"><p class="custom-block-title">Note</p><p>Need to enter correct numbers, otherwise clicking will fail.</p></div><p><strong>2. Click input box is grayed out/cannot open click settings</strong></p><p>This may be because you are currently clicking, need to click the <code>Stop</code> button to stop before entering again.</p><img class="input_disable" alt="Click input box grayed out"><br><img class="stop_click" alt="Cannot open click settings"><p><strong>3. Software update failed: Update service not enabled</strong></p><p>Please go to <code>Settings</code>, select <code>Update</code> on the left, then enable <code>Enable Update</code></p><img class="update_disable" alt="Update service not enabled"><p><strong>4. Prompt that package manager folder does not exist, pops up every time</strong></p><p>You can go to Settings - Notifications - turn off <code>Official extension package missing warning</code></p><img class="ipk_not_found" alt="Prompt that package manager folder does not exist"><p><strong>5. Checkbox click invalid</strong></p><p>You may have clicked on the text area. Clickmouse checkbox needs to be clicked inside the box to be effective.</p>',35))]))}});export{f as __pageData,b as default};
